begin;
select no_plan();
insert into auth.users(id,email) values('ab100000-0000-0000-0000-000000000001','owner@advanced.test'),('ab100000-0000-0000-0000-000000000002','member@advanced.test');
insert into public.tenants(id,name,slug) values('ab200000-0000-0000-0000-000000000001','Advanced business','advanced-reservations');
insert into public.tenant_memberships(tenant_id,user_id,role) values('ab200000-0000-0000-0000-000000000001','ab100000-0000-0000-0000-000000000001','owner'),('ab200000-0000-0000-0000-000000000001','ab100000-0000-0000-0000-000000000002','member');
insert into public.properties(id,tenant_id,name,property_type,timezone) values('ab300000-0000-0000-0000-000000000001','ab200000-0000-0000-0000-000000000001','Advanced Hotel','hotel','UTC'),('ab300000-0000-0000-0000-000000000002','ab200000-0000-0000-0000-000000000001','Other Hotel','hotel','UTC');
insert into public.property_memberships(tenant_id,property_id,user_id) values('ab200000-0000-0000-0000-000000000001','ab300000-0000-0000-0000-000000000001','ab100000-0000-0000-0000-000000000002');
insert into public.accommodation_types(id,tenant_id,property_id,name,max_occupancy,base_rate) values('ab400000-0000-0000-0000-000000000001','ab200000-0000-0000-0000-000000000001','ab300000-0000-0000-0000-000000000001','Deluxe',2,100);
insert into public.accommodation_units(id,tenant_id,property_id,type_id,name,housekeeping_status) values
('ab500000-0000-0000-0000-000000000001','ab200000-0000-0000-0000-000000000001','ab300000-0000-0000-0000-000000000001','ab400000-0000-0000-0000-000000000001','101','clean'),
('ab500000-0000-0000-0000-000000000002','ab200000-0000-0000-0000-000000000001','ab300000-0000-0000-0000-000000000001','ab400000-0000-0000-0000-000000000001','102','clean'),
('ab500000-0000-0000-0000-000000000003','ab200000-0000-0000-0000-000000000001','ab300000-0000-0000-0000-000000000001','ab400000-0000-0000-0000-000000000001','103','dirty'),
('ab500000-0000-0000-0000-000000000004','ab200000-0000-0000-0000-000000000001','ab300000-0000-0000-0000-000000000001','ab400000-0000-0000-0000-000000000001','104','clean');
select set_config('test.day',((now() at time zone 'UTC')::date)::text,true);
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"ab100000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select public.create_inventory_block('ab500000-0000-0000-0000-000000000002',current_setting('test.day')::date,current_setting('test.day')::date+10,'Maintenance');
select public.create_inventory_block('ab500000-0000-0000-0000-000000000004',current_setting('test.day')::date,current_setting('test.day')::date+10,'Maintenance');
select is((public.frontdesk_quote('ab300000-0000-0000-0000-000000000001','ab400000-0000-0000-0000-000000000001',current_setting('test.day')::date,current_setting('test.day')::date+2,2,0)->>'total')::numeric,200::numeric,'quote uses authoritative room price');
select is(jsonb_array_length(public.frontdesk_quote('ab300000-0000-0000-0000-000000000001','ab400000-0000-0000-0000-000000000001',current_setting('test.day')::date,current_setting('test.day')::date+2,2,0)->'rooms'),2,'inventory blocks are excluded from quote');
select lives_ok($$select set_config('test.res',public.frontdesk_create('ab300000-0000-0000-0000-000000000001','ab600000-0000-0000-0000-000000000001','Booking Guest','+910001','guest@example.test','ab400000-0000-0000-0000-000000000001',current_setting('test.day')::date,current_setting('test.day')::date+2,2,0,null,'ab500000-0000-0000-0000-000000000001','Late arrival','direct',200)::text,true)$$,'atomic booking succeeds');
select is(public.frontdesk_create('ab300000-0000-0000-0000-000000000001','ab600000-0000-0000-0000-000000000001','Retry',null,null,'ab400000-0000-0000-0000-000000000001',current_setting('test.day')::date,current_setting('test.day')::date+2,2,0,null,null,'','direct',200),current_setting('test.res')::uuid,'retry returns original reservation');
select is((select count(*)::int from public.guests where tenant_id='ab200000-0000-0000-0000-000000000001'),1,'retry did not create duplicate guest');
select throws_ok($$select public.frontdesk_create('ab300000-0000-0000-0000-000000000001','ab600000-0000-0000-0000-000000000002','Wrong quote',null,null,'ab400000-0000-0000-0000-000000000001',current_setting('test.day')::date,current_setting('test.day')::date+2,2,0,null,null,'','direct',99)$$,'22023',null,'stale quote is rejected');
select throws_ok($$select public.frontdesk_create('ab300000-0000-0000-0000-000000000001','ab600000-0000-0000-0000-000000000003','Conflicting Guest',null,null,'ab400000-0000-0000-0000-000000000001',current_setting('test.day')::date,current_setting('test.day')::date+2,2,0,null,'ab500000-0000-0000-0000-000000000001','','direct',200)$$,'23P01',null,'competing room request is rejected');
select is((select count(*)::int from public.guests where tenant_id='ab200000-0000-0000-0000-000000000001'),1,'failed allocation rolls back guest creation');
select throws_ok($$select public.frontdesk_quote('ab300000-0000-0000-0000-000000000001','ab400000-0000-0000-0000-000000000001',current_setting('test.day')::date,current_setting('test.day')::date+2,2,1)$$,'22023',null,'capacity is enforced');
select is((public.reservation_workspace('ab300000-0000-0000-0000-000000000001','{"q":"BOOKING GUEST","view":"all"}')->>'total')::int,1,'search finds guest case-insensitively');
select is((public.reservation_workspace('ab300000-0000-0000-0000-000000000002','{"view":"all"}')->>'total')::int,0,'list is scoped to selected hotel');
select throws_ok($$select public.reservation_detail('ab300000-0000-0000-0000-000000000002',current_setting('test.res')::uuid)$$,'P0002',null,'detail cannot mix property and reservation IDs');
select is(jsonb_array_length(public.frontdesk_quote('ab300000-0000-0000-0000-000000000001','ab400000-0000-0000-0000-000000000001',current_setting('test.day')::date,current_setting('test.day')::date+2,2,0,null,current_setting('test.res')::uuid)->'rooms'),2,'editing excludes own hold but still excludes blocks');
select throws_ok($$select public.frontdesk_update(current_setting('test.res')::uuid,99,'ab400000-0000-0000-0000-000000000001',current_setting('test.day')::date,current_setting('test.day')::date+3,2,0,null,null,300)$$,'40001',null,'stale edits are rejected');
select throws_ok($$select public.frontdesk_update(current_setting('test.res')::uuid,1,'ab400000-0000-0000-0000-000000000001',current_setting('test.day')::date,current_setting('test.day')::date+3,2,0,null,'ab500000-0000-0000-0000-000000000002',300)$$,'23P01',null,'edit to blocked room fails');
select is((select check_out from public.reservations where id=current_setting('test.res')::uuid),current_setting('test.day')::date+2,'failed edit preserves original dates');
select is((select count(*)::int from public.unit_holds where reservation_id=current_setting('test.res')::uuid and active),1,'failed edit preserves original active hold');
select lives_ok($$select public.frontdesk_update(current_setting('test.res')::uuid,1,'ab400000-0000-0000-0000-000000000001',current_setting('test.day')::date,current_setting('test.day')::date+3,2,0,null,'ab500000-0000-0000-0000-000000000001',300)$$,'confirmed stay can be extended and repriced');
update public.accommodation_units set housekeeping_status='dirty' where id='ab500000-0000-0000-0000-000000000001';
select throws_ok($$select public.frontdesk_action(current_setting('test.res')::uuid,2,'check_in')$$,'22023',null,'dirty-room check-in is blocked');
update public.accommodation_units set housekeeping_status='clean' where id='ab500000-0000-0000-0000-000000000001';
select lives_ok($$select public.frontdesk_action(current_setting('test.res')::uuid,2,'check_in')$$,'clean room can be checked in');
select throws_ok($$select public.frontdesk_move(current_setting('test.res')::uuid,3,'ab500000-0000-0000-0000-000000000003','Guest preference')$$,'22023',null,'in-house move to dirty room is blocked');
update public.accommodation_units set housekeeping_status='clean' where id='ab500000-0000-0000-0000-000000000003';
reset role;
insert into public.reservations(id,tenant_id,property_id,guest_id,status,check_in,check_out,total_amount,currency)
select 'ab700000-0000-0000-0000-000000000001',tenant_id,property_id,guest_id,'checked_in',current_setting('test.day')::date-2,current_setting('test.day')::date,100,'INR' from public.reservations where id=current_setting('test.res')::uuid;
insert into public.unit_holds(tenant_id,property_id,unit_id,during,kind,reservation_id) values('ab200000-0000-0000-0000-000000000001','ab300000-0000-0000-0000-000000000001','ab500000-0000-0000-0000-000000000003',daterange(current_setting('test.day')::date-2,current_setting('test.day')::date,'[)'),'reservation','ab700000-0000-0000-0000-000000000001');
set local role authenticated;
select throws_ok($$select public.frontdesk_move(current_setting('test.res')::uuid,3,'ab500000-0000-0000-0000-000000000003','Guest preference')$$,'22023',null,'late previous guest blocks an in-house room move even beyond scheduled checkout');
reset role;
update public.reservations set status='checked_out' where id='ab700000-0000-0000-0000-000000000001';
set local role authenticated;
select lives_ok($$select public.frontdesk_move(current_setting('test.res')::uuid,3,'ab500000-0000-0000-0000-000000000003','Guest preference')$$,'room move succeeds atomically');
select is((select housekeeping_status from public.accommodation_units where id='ab500000-0000-0000-0000-000000000001'),'dirty','previous room is marked dirty');
select is((select count(*)::int from public.tasks where unit_id='ab500000-0000-0000-0000-000000000001' and kind='housekeeping'),1,'in-house move creates cleaning task');
select lives_ok($$select public.frontdesk_action(current_setting('test.res')::uuid,4,'notes','New guest preference')$$,'notes can be updated');
select throws_ok($$select public.frontdesk_action(current_setting('test.res')::uuid,4,'notes','Stale preference')$$,'40001',null,'stale note cannot overwrite new note');
select lives_ok($$select public.frontdesk_action(current_setting('test.res')::uuid,5,'post_charges')$$,'room charges post idempotently');
select is((public.reservation_detail('ab300000-0000-0000-0000-000000000001',current_setting('test.res')::uuid)#>>'{finance,checkout_balance}')::numeric,300::numeric,'detail reports full checkout balance');
select throws_ok($$select public.frontdesk_action(current_setting('test.res')::uuid,5,'check_out')$$,'22023',null,'unsettled checkout is blocked');
select public.collect_folio_payment((select id from public.folios where reservation_id=current_setting('test.res')::uuid),300,'cash');
select lives_ok($$select public.frontdesk_action(current_setting('test.res')::uuid,5,'check_out')$$,'settled stay can check out');
select is((select status from public.reservations where id=current_setting('test.res')::uuid),'checked_out','checkout status is recorded');
select is((select housekeeping_status from public.accommodation_units where id='ab500000-0000-0000-0000-000000000003'),'dirty','checkout marks destination dirty');
select set_config('test.future',public.frontdesk_create('ab300000-0000-0000-0000-000000000001','ab600000-0000-0000-0000-000000000004','Future Guest',null,null,'ab400000-0000-0000-0000-000000000001',current_setting('test.day')::date+20,current_setting('test.day')::date+21,1,0,null,null,'','direct',100)::text,true);
select throws_ok($$select public.frontdesk_action(current_setting('test.future')::uuid,1,'check_in')$$,'22023',null,'future check-in is blocked');
select throws_ok($$select public.frontdesk_action(current_setting('test.future')::uuid,1,'no_show','Not here')$$,'22023',null,'future no-show is blocked');
select throws_ok($$select public.frontdesk_action(current_setting('test.future')::uuid,1,'cancel','')$$,'22023',null,'cancellation requires reason');
select lives_ok($$select public.frontdesk_action(current_setting('test.future')::uuid,1,'cancel','Guest changed plans')$$,'cancellation succeeds with reason');
select is((select count(*)::int from public.unit_holds where reservation_id=current_setting('test.future')::uuid and active),0,'cancellation releases room');
select set_config('test.noshow',public.frontdesk_create('ab300000-0000-0000-0000-000000000001','ab600000-0000-0000-0000-000000000005','Absent Guest',null,null,'ab400000-0000-0000-0000-000000000001',current_setting('test.day')::date,current_setting('test.day')::date+1,1,0,null,'ab500000-0000-0000-0000-000000000001','','direct',100)::text,true);
select lives_ok($$select public.frontdesk_action(current_setting('test.noshow')::uuid,1,'no_show','Guest did not arrive')$$,'due arrival can be marked no-show');
select is((select count(*)::int from public.unit_holds where reservation_id=current_setting('test.noshow')::uuid and active),0,'no-show releases room');
select is((public.reservation_detail('ab300000-0000-0000-0000-000000000001',current_setting('test.future')::uuid)#>>'{finance,checkout_balance}')::numeric,0::numeric,'cancelled reservation does not show unposted nights as payable');
select throws_ok($$select public.frontdesk_create('ab300000-0000-0000-0000-000000000001','ab600000-0000-0000-0000-000000000010','Invalid Email',null,'not-an-email','ab400000-0000-0000-0000-000000000001',current_setting('test.day')::date+30,current_setting('test.day')::date+31,1,0,null,null,'','direct',100)$$,'22023',null,'database rejects malformed guest email');
reset role;
insert into public.reservations(tenant_id,property_id,guest_id,check_in,check_out,total_amount,currency)
select 'ab200000-0000-0000-0000-000000000001','ab300000-0000-0000-0000-000000000002',(select guest_id from public.reservations where id=current_setting('test.res')::uuid),current_setting('test.day')::date+40+n,current_setting('test.day')::date+41+n,100,'INR' from generate_series(1,21)n;
set local role authenticated;
select is((public.reservation_workspace('ab300000-0000-0000-0000-000000000002','{"view":"all"}')->>'total')::int,21,'list count is not capped at the page size');
select is(jsonb_array_length(public.reservation_workspace('ab300000-0000-0000-0000-000000000002','{"view":"all"}')->'rows'),20,'list returns a bounded first page');
select is(jsonb_array_length(public.reservation_workspace('ab300000-0000-0000-0000-000000000002','{"view":"all","page":2}')->'rows'),1,'remaining reservation is reachable on page two');
select set_config('request.jwt.claims','{"sub":"ab100000-0000-0000-0000-000000000002","role":"authenticated"}',true);
select throws_ok($$select public.reservation_workspace('ab300000-0000-0000-0000-000000000001')$$,'42501',null,'staff without reservation read access cannot query list');
select throws_ok($$select public.frontdesk_quote('ab300000-0000-0000-0000-000000000001','ab400000-0000-0000-0000-000000000001',current_setting('test.day')::date,current_setting('test.day')::date+2,1,0)$$,'42501',null,'staff without write access cannot quote');
select throws_ok($$select public.frontdesk_action(current_setting('test.res')::uuid,6,'notes','Unauthorized')$$,'42501',null,'staff cannot mutate stay without permission');
reset role;
insert into public.roles(id,tenant_id,key,name) values('ab800000-0000-0000-0000-000000000001','ab200000-0000-0000-0000-000000000001','reservation_viewer','Reservation viewer');
insert into public.role_permissions(role_id,permission_key) values('ab800000-0000-0000-0000-000000000001','reservations.read');
insert into public.user_roles(property_id,user_id,role_id) values('ab300000-0000-0000-0000-000000000001','ab100000-0000-0000-0000-000000000002','ab800000-0000-0000-0000-000000000001');
set local role authenticated;
select ok(not (public.reservation_detail('ab300000-0000-0000-0000-000000000001',current_setting('test.res')::uuid) ? 'finance'),'reservation viewer cannot read folio/payment summary');
select ok(not (public.reservation_workspace('ab300000-0000-0000-0000-000000000001')->>'can_write')::boolean,'read-only reservation access does not grant booking rights');
reset role;set local role anon;
select throws_ok($$select public.reservation_workspace('ab300000-0000-0000-0000-000000000001')$$,'42501',null,'anonymous list access is denied');
select * from finish();
rollback;
